from decimal import Decimal

import pytest
from sqlalchemy import select
from sqlalchemy.exc import OperationalError
from werkzeug.security import check_password_hash


def _app():
    import app as inventory_app
    return inventory_app


def get_csrf_token(client, page="/login"):
    """Get the CSRF token generated by a GET request."""
    response = client.get(page)
    assert response.status_code == 200

    with client.session_transaction() as session:
        return session["_csrf_token"]


def register_user(client, username="testuser", password="testpassword123"):
    token = get_csrf_token(client, "/register")

    return client.post(
        "/register",
        data={
            "_csrf_token": token,
            "username": username,
            "password": password,
            "confirm_password": password,
        },
        follow_redirects=True,
    )


def login_user(client, username="testuser", password="testpassword123"):
    token = get_csrf_token(client, "/login")

    return client.post(
        "/login",
        data={
            "_csrf_token": token,
            "username": username,
            "password": password,
        },
        follow_redirects=True,
    )


def logout_user(client):
    token = get_csrf_token(client, "/dashboard")

    return client.post("/logout", data={"_csrf_token": token}, follow_redirects=True)


def add_product(
    client,
    sku="TEST-001",
    name="Test Keyboard",
    category="Electronics",
    price="1500",
    quantity="10",
    reorder_level="3",
):
    token = get_csrf_token(client, "/dashboard")

    return client.post(
        "/products/add",
        data={
            "_csrf_token": token,
            "sku": sku,
            "name": name,
            "category": category,
            "price": price,
            "quantity": quantity,
            "reorder_level": reorder_level,
        },
        follow_redirects=True,
    )


def get_product(product_sku):
    """Read a product straight from the MySQL test database."""
    from models import Product

    with _app().SessionLocal() as db:
        return db.scalar(select(Product).where(Product.sku == product_sku))


def get_user(username):
    from models import User

    with _app().SessionLocal() as db:
        return db.scalar(select(User).where(User.username == username))


