def test_edit_product(client):
    register_user(client)
    login_user(client)
    add_product(client)

    product = get_product("TEST-001")
    assert product is not None

    product_id = product.id
    token = get_csrf_token(client, "/dashboard")

    response = client.post(
        f"/products/{product_id}/edit",
        data={
            "_csrf_token": token,
            "sku": "TEST-001",
            "name": "Updated Keyboard",
            "category": "Electronics",
            "price": "1800",
            "quantity": "15",
            "reorder_level": "4",
        },
        follow_redirects=True,
    )

    assert response.status_code == 200

    updated_product = get_product("TEST-001")

    assert updated_product is not None
    assert updated_product.name == "Updated Keyboard"
    assert updated_product.price == 1800
    assert updated_product.quantity == 15
    assert updated_product.reorder_level == 4


