# --------------------------------------------------
# 5. USER DATA ISOLATION
# --------------------------------------------------

def test_user_cannot_see_another_users_products(client):
    register_user(client, username="firstuser")
    login_user(client, username="firstuser")

    add_product(
        client,
        sku="PRIVATE-001",
        name="Private Product",
    )

    logout_user(client)

    register_user(client, username="seconduser")
    login_user(client, username="seconduser")

    response = client.get("/dashboard")

    assert response.status_code == 200
    assert b"Private Product" not in response.data


def test_user_cannot_edit_another_users_product(client):
    register_user(client, username="firstuser")
    login_user(client, username="firstuser")
    add_product(
        client,
        sku="OWNER-001",
        name="Original Product",
    )

    product = get_product("OWNER-001")
    product_id = product.id

    logout_user(client)

    register_user(client, username="seconduser")
    login_user(client, username="seconduser")

    token = get_csrf_token(client, "/dashboard")

    response = client.post(
        f"/products/{product_id}/edit",
        data={
            "_csrf_token": token,
            "sku": "OWNER-001",
            "name": "Hacked Product",
            "category": "General",
            "price": "1",
            "quantity": "999",
            "reorder_level": "0",
        },
        follow_redirects=True,
    )

    # The other user's product must remain unchanged.
    product_after_request = get_product("OWNER-001")

    assert product_after_request is not None
    assert product_after_request.name == "Original Product"
    assert product_after_request.quantity == 10


def test_user_cannot_delete_another_users_product(client):
    register_user(client, username="firstuser")
    login_user(client, username="firstuser")
    add_product(
        client,
        sku="OWNER-002",
        name="Protected Product",
    )

    product = get_product("OWNER-002")
    product_id = product.id

    logout_user(client)

    register_user(client, username="seconduser")
    login_user(client, username="seconduser")

    token = get_csrf_token(client, "/dashboard")

    client.post(
        f"/products/{product_id}/delete",
        data={"_csrf_token": token},
        follow_redirects=True,
    )

    # The product must still belong to its original owner.
    product_after_request = get_product("OWNER-002")

    assert product_after_request is not None
    assert product_after_request.name == "Protected Product"


