def test_search_and_category_filter(client):
    register_user(client)
    login_user(client)
    add_product(client, sku="KB-1", name="Keyboard", category="Accessories")
    add_product(client, sku="MN-1", name="Monitor", category="Displays")

    by_search = client.get("/dashboard?q=keyboard")
    by_category = client.get("/dashboard?category=Displays")

    assert b"Keyboard" in by_search.data and b"Monitor" not in by_search.data
    assert b"Monitor" in by_category.data and b"Keyboard" not in by_category.data


