# --------------------------------------------------
# 7. DATABASE FAILURE HANDLING
# --------------------------------------------------

def _connection_error():
    return OperationalError("SELECT 1", {}, Exception("simulated connection loss"))


def test_database_outage_returns_503_page(client, monkeypatch):
    inventory_app = _app()
    with client.session_transaction() as session:
        session["user_id"] = 1
        session["username"] = "ghost"

    def broken_db():
        raise _connection_error()

    monkeypatch.setattr(inventory_app, "get_db", broken_db)

    response = client.get("/dashboard")

    assert response.status_code == 503
    assert b"temporarily unavailable" in response.data
    assert b"simulated connection loss" not in response.data  # no internals leaked


def test_healthz_returns_503_when_database_is_down(client, monkeypatch):
    class BrokenEngine:
        def connect(self):
            raise _connection_error()

    monkeypatch.setattr(_app(), "engine", BrokenEngine())

    response = client.get("/healthz")

    assert response.status_code == 503
